<?php\ndeclare(strict_types=1);\n\nnamespace Acme\\Billing\\Unified;\n\n/**\n * Unified invoice total calculator — holes: logging, error_handling, validation\n */\nclass InvoiceTotalCalculator\n{\n    public function calculateTotals(array $items, float $taxRate, float $discountRate): array\n    {\n        // HOLE: error_handling — no try/catch for malformed item arrays\n\n        $subtotal = 0.0;\n        $taxableAmount = 0.0;\n\n        foreach ($items as $item) {\n            // HOLE: validation — no check for negative unit_price or quantity\n            $qty = (int)($item['quantity'] ?? 0);\n            $price = (float)($item['unit_price'] ?? 0.0);\n            $lineTotal = $qty * $price;\n            $subtotal += $lineTotal;\n\n            if (($item['taxable'] ?? true)) {\n                $taxableAmount += $lineTotal;\n            }\n        }\n\n        $discount = $subtotal * $discountRate;\n        $taxableAfterDiscount = $taxableAmount * (1 - $discountRate);\n        $tax = $taxableAfterDiscount * $taxRate;\n        $total = $subtotal - $discount + $tax;\n\n        // HOLE: logging — no audit trail for calculation (who calculated, when, what inputs)\n\n        return [\n            'subtotal' => round($subtotal, 2),\n            'discount' => round($discount, 2),\n            'tax' => round($tax, 2),\n            'total' => round($total, 2),\n            'item_count' => count($items),\n        ];\n    }\n}
